/* ---------- i18n ---------- */
/* The page language is fixed by its URL (<html lang> is set in the HTML). */
function pageLang() {
  return document.documentElement.lang === 'ko' ? 'ko' : 'en';
}

/* Korean pages already ship Korean body text; this only translates the
 * header/footer that renderHeader/renderFooter insert in English. */
function applyKorean() {
  document.querySelectorAll('[data-i18n]').forEach((el) => {
    const ko = KO[el.dataset.i18n];
    if (ko !== undefined) el.textContent = ko;
  });
  document.querySelectorAll('[data-i18n-ph]').forEach((el) => {
    const ko = KO[el.dataset.i18nPh];
    if (ko !== undefined) el.setAttribute('placeholder', ko);
  });
}

/* ---------- Contact form ---------- */
function mailtoFallback(form) {
  const d = new FormData(form);
  const body = [
    "Name: " + d.get("name"),
    "Email: " + d.get("email"),
    "Business Type: " + d.get("business_type"),
    "",
    d.get("message"),
  ].join("\n");
  const subject = "Website inquiry — " + d.get("name");
  window.location.href = "mailto:" + FORM.CONTACT_EMAIL +
    "?subject=" + encodeURIComponent(subject) + "&body=" + encodeURIComponent(body);
}

function initForm() {
  const form = document.getElementById("contactForm");
  if (!form) return;
  const errorEl = document.getElementById("formError");
  const sendErrorEl = document.getElementById("formSendError");
  const successEl = document.getElementById("formSuccess");
  const submitBtn = document.getElementById("formSubmit");
  form.elements.access_key.value = FORM.WEB3FORMS_KEY;

  form.addEventListener("submit", async (e) => {
    e.preventDefault();
    successEl.classList.add("hidden");
    sendErrorEl.classList.add("hidden");
    if (!form.checkValidity()) {
      errorEl.classList.remove("hidden");
      return;
    }
    errorEl.classList.add("hidden");

    if (!FORM.WEB3FORMS_KEY) {
      mailtoFallback(form);
      return;
    }

    submitBtn.disabled = true;
    try {
      const res = await fetch(form.action, { method: "POST", body: new FormData(form), headers: { Accept: "application/json" } });
      const json = await res.json().catch(() => ({}));
      if (!res.ok || json.success === false) throw new Error(json.message || "Request failed");
      form.reset();
      successEl.classList.remove("hidden");
    } catch (err) {
      sendErrorEl.classList.remove("hidden");
    } finally {
      submitBtn.disabled = false;
    }
  });
}

/* ---------- Home hero slider ---------- */
function initHeroSlider() {
  const root = document.getElementById('heroSlider');
  if (!root) return;
  const track = root.querySelector('.hero-slider__track');
  const slides = [...root.querySelectorAll('.hero-slide')];
  const dotsWrap = root.querySelector('.hero-slider__dots');
  const AUTOPLAY_MS = 7000; // 0 turns autoplay off
  const reduceMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  let index = 0;
  let timer = null;

  const dots = slides.map((_, i) => {
    const b = document.createElement('button');
    b.type = 'button';
    b.className = 'hero-slider__dot border-brass/60';
    b.setAttribute('aria-label', 'Slide ' + (i + 1));
    b.addEventListener('click', () => { go(i); restart(); });
    dotsWrap.appendChild(b);
    return b;
  });

  function go(i) {
    index = (i + slides.length) % slides.length;
    track.style.transform = 'translateX(' + (-index * 100) + '%)';
    slides.forEach((s, n) => {
      const active = n === index;
      s.setAttribute('aria-hidden', String(!active));
      s.inert = !active;
    });
    dots.forEach((d, n) => {
      const active = n === index;
      d.setAttribute('aria-current', String(active));
      d.classList.toggle('bg-brass', active);
    });
  }

  function stop() { clearInterval(timer); timer = null; }
  function restart() {
    stop();
    if (AUTOPLAY_MS && !reduceMotion) timer = setInterval(() => go(index + 1), AUTOPLAY_MS);
  }

  root.querySelector('.hero-slider__arrow--prev').addEventListener('click', () => { go(index - 1); restart(); });
  root.querySelector('.hero-slider__arrow--next').addEventListener('click', () => { go(index + 1); restart(); });
  root.addEventListener('keydown', (e) => {
    if (e.key === 'ArrowLeft') { go(index - 1); restart(); }
    if (e.key === 'ArrowRight') { go(index + 1); restart(); }
  });

  // Pause while the visitor is reading or interacting
  root.addEventListener('mouseenter', stop);
  root.addEventListener('mouseleave', restart);
  root.addEventListener('focusin', stop);
  root.addEventListener('focusout', restart);
  document.addEventListener('visibilitychange', () => (document.hidden ? stop() : restart()));

  // Touch swipe
  let startX = null;
  let startY = 0;
  root.addEventListener('touchstart', (e) => { startX = e.touches[0].clientX; startY = e.touches[0].clientY; stop(); }, { passive: true });
  root.addEventListener('touchend', (e) => {
    if (startX === null) return;
    const dx = e.changedTouches[0].clientX - startX;
    const dy = e.changedTouches[0].clientY - startY;
    if (Math.abs(dx) > 40 && Math.abs(dx) > Math.abs(dy)) go(index + (dx < 0 ? 1 : -1));
    startX = null;
    restart();
  });

  go(0);
  restart();
}

/* ---------- Boot ---------- */
document.addEventListener('DOMContentLoaded', () => {
  const page = document.body.dataset.page;
  const headerSlot = document.getElementById('site-header');
  const footerSlot = document.getElementById('site-footer');
  if (headerSlot) headerSlot.outerHTML = renderHeader(page);
  if (footerSlot) footerSlot.outerHTML = renderFooter();

  // Resolve shared link targets
  document.querySelectorAll('[data-link]').forEach((a) => {
    const url = LINKS[a.dataset.link];
    if (!url) return;
    a.setAttribute('href', url);
    if (/^https?:/.test(url)) { a.target = '_blank'; a.rel = 'noopener'; }
  });

  if (pageLang() === 'ko') applyKorean();

  const menuBtn = document.getElementById('menuBtn');
  const mobileMenu = document.getElementById('mobileMenu');
  menuBtn.addEventListener('click', () => {
    const open = mobileMenu.classList.toggle('hidden') === false;
    menuBtn.setAttribute('aria-expanded', String(open));
  });

  initForm();
  initHeroSlider();
});
